arguments.command:
cd /tmp/sv-96b3ab3836f947ada8032ee05251aa6f/symbols && \
# Use nm -D to get dynamic symbols, then resolve each address
# Offsets from tombstone for libmonosgen-2.0.so: 0x222098, 0x222234, 0x19bac0, 0x19bc14
nm -D --defined-only libmonosgen-2.0.so 2>/dev/null | sort | awk '
BEGIN {
  addrs[1] = 0x222098
  addrs[2] = 0x222234
  addrs[3] = 0x19bac0
  addrs[4] = 0x19bc14
}
{
  addr = strtonum("0x" $1)
  name = $3
  for (i in addrs) {
    if (addr <= addrs[i]) {
      best[i] = name
      bestaddr[i] = addr
    }
  }
}
END {
  for (i = 1; i <= 4; i++) {
    printf "0x%x -> %s+0x%x\n", addrs[i], best[i], addrs[i] - bestaddr[i]
  }
}' 2>&1 | head -20

